  ('87d6dd3e-a6a9-41fd-87e1-34cc53e3da78'::uuid, 'Q024', -2, 'deduite'::affinite_confiance, 'https://www.jean-jaures.org/publication/les-contradictions-du-programme-social-du-rassemblement-national/', 'Idéologie RN centrée sur le mérite et la conditionnalité du travail, incompatible avec un revenu universel inconditionnel.'),
