from (values
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q001', 2, 'sourcee'::affinite_confiance, 'https://twitter.com/jlmelenchon/status/1469224197272621057', 'Mélenchon a déclaré vouloir rendre le vote obligatoire et compter le vote blanc s''il est élu.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q002', 2, 'sourcee'::affinite_confiance, 'https://twitter.com/jlmelenchon/status/1469224197272621057', 'Le RIC (législatif, abrogatoire, révocatoire, constituant) est une proposition historique et centrale de LFI, réaffirmée dans ce message.'),
