  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q004', 2, 'sourcee'::affinite_confiance, 'https://www.lagazettedescommunes.com/495789/les-propositions-institutionnelles-de-jean-luc-melenchon-en-route-pour-une-vie-republique/', 'Propose une Assemblée élue à la proportionnelle intégrale dans le cadre de la 6e République.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q005', 2, 'deduite'::affinite_confiance, NULL, 'Le projet de 6e République porté par LFI est historiquement unicaméral (suppression du Sénat), cohérent avec son soutien à la proportionnelle intégrale.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q006', 0, 'deduite'::affinite_confiance, NULL, 'Aucune information trouvée, même par déduction idéologique — position neutre provisoire (0), à réviser dès que des éléments seront disponibles.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q007', 1, 'deduite'::affinite_confiance, 'https://www.institutmontaigne.org/presidentielle-2022/jean-luc-melenchon/rendre-effectif-le-principe-du-non-cumul-des-mandats-et-des-indemnites/', 'Cohérent avec le principe général de non-cumul des mandats et fonctions, sans mesure spécifique trouvée sur les ministres.'),
