  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q009', 2, 'sourcee'::affinite_confiance, 'https://www.franceinfo.fr/politique/melenchon/politique-la-revocation-des-elus-une-proposition-de-la-france-insoumise_4952340.html', 'Proposition constante de LFI: révocation des élus en cours de mandat par référendum local à l''initiative citoyenne.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q010', -1, 'deduite'::affinite_confiance, NULL, 'LFI privilégie davantage de représentation citoyenne (Assemblée constituante, conventions citoyennes) plutôt qu''une réduction du nombre d''élus.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q011', -2, 'deduite'::affinite_confiance, 'https://melenchon2027.fr/programme/decouvrir/', 'LFI promeut l''annulation partielle de la dette plutôt que la baisse de la dépense publique; rejette la logique d''austérité touchant les services publics.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q012', 2, 'deduite'::affinite_confiance, 'https://lafacture2027.fr/programme-fiscal-melenchon-2027', 'Le programme 2027 rétablit l''ISF et l''élargit (volet climatique), allant au-delà de la version d''avant 2017.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q013', 0, 'deduite'::affinite_confiance, 'https://www.institutmontaigne.org/presidentielle-2022/jean-luc-melenchon/augmenter-les-droits-de-succession-sur-les-plus-hauts-patrimoines-et-creer-un-heritage-maximal-de-12-me/', 'Position nuancée: alourdissement sur les gros patrimoines (plafond à 12M€) mais relèvement des abattements pour les petites successions, donc ni accord ni désaccord franc avec un allègement général.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q014', 2, 'sourcee'::affinite_confiance, 'https://lafacture2027.fr/programme-fiscal-melenchon-2027', 'Programme 2027: SMIC porté à 1600€ net.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q015', 1, 'deduite'::affinite_confiance, 'https://melenchon2027.fr/programme/decouvrir/', 'Programme prévoit le passage à 32h pour métiers pénibles/de nuit et la généralisation progressive par négociation collective, indiquant une tendance à réduire la durée légale sous 35h à terme.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q016', 1, 'deduite'::affinite_confiance, 'https://lafacture2027.fr/programme-fiscal-melenchon-2027', 'Cohérent avec la logique fiscale de LFI visant à taxer davantage les entreprises favorisant les dividendes plutôt que les salaires/investissements, sans citation exacte trouvée.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q017', -1, 'deduite'::affinite_confiance, 'https://melenchon2027.fr/programme/decouvrir/', 'Depuis 2017-2022, LFI a remplacé la perspective de sortie de l''euro par une stratégie de désobéissance aux traités européens (Plan A/B), sans faire de la sortie de la monnaie unique un objectif affiché.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q018', -2, 'deduite'::affinite_confiance, 'https://melenchon2027.fr/programme/decouvrir/', 'LFI promeut l''annulation d''une partie de la dette détenue par la BCE plutôt que sa réduction prioritaire avant toute dépense sociale.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q019', 2, 'deduite'::affinite_confiance, 'https://votons-2027.fr/candidats/melenchon/programme/economie', 'Ligne constante de LFI: conditionner les aides publiques aux entreprises au maintien de l''emploi et à des objectifs sociaux/écologiques contraignants, avec remboursement en cas de non-respect.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q020', 2, 'deduite'::affinite_confiance, 'https://votons-2027.fr/candidats/melenchon/programme/economie', 'La lutte contre la fraude et l''évasion fiscales est présentée comme une priorité majeure, avec un impôt universel sur les entreprises et les particuliers.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q021', 2, 'sourcee'::affinite_confiance, 'https://www.planet.fr/politique-retour-de-la-retraite-a-60-ans-cest-possible-dapres-jean-luc-melenchon.2997356.29334.html', 'Mélenchon a lancé sa candidature 2027 en réaffirmant le retour à la retraite à 60 ans à taux plein pour 40 annuités, via l''abrogation de la réforme 2023.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q022', -2, 'deduite'::affinite_confiance, 'https://votons-2027.fr/candidats/melenchon/programme/economie', 'LFI s''oppose aux logiques de conditionnalité/activité obligatoire du RSA, défendant l''inconditionnalité des minima sociaux.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q023', -2, 'deduite'::affinite_confiance, 'https://votons-2027.fr/candidats/melenchon/programme/economie', 'LFI a constamment combattu les réformes successives durcissant les règles de l''assurance chômage (2019, 2021, 2023).'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q024', -1, 'sourcee'::affinite_confiance, 'https://www.institutmontaigne.org/presidentielle-2022/jean-luc-melenchon/creer-une-garantie-demploi-au-smic-pour-les-chomeurs-de-longue-duree-dans-un-secteur-durgence/', 'LFI privilégie une garantie d''emploi et une garantie d''autonomie sous conditions de ressources plutôt qu''un revenu universel inconditionnel pour tous les citoyens.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q025', 1, 'deduite'::affinite_confiance, 'https://melenchon2027.fr/programme/decouvrir/', 'Cohérent avec la réduction du temps de travail vers 32h promue par LFI, même si la formulation exacte "semaine de 4 jours" n''est pas la terminologie du programme.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q026', 2, 'deduite'::affinite_confiance, NULL, 'Cohérent avec sa défense du retour à la retraite à 60 ans et sa ligne générale de protection de l''emploi senior.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q027', 1, 'deduite'::affinite_confiance, 'https://votons-2027.fr/candidats/melenchon/programme/economie', 'Ligne constante de LFI en faveur de la lutte contre la précarité de l''emploi et du CDI comme norme.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q028', -2, 'deduite'::affinite_confiance, 'https://votons-2027.fr/candidats/melenchon/programme/economie', 'LFI est critique des exonérations de cotisations sociales jugées peu efficaces pour l''emploi et propose de les réévaluer plutôt que de les étendre.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q029', 2, 'deduite'::affinite_confiance, 'https://votons-2027.fr/candidats/melenchon/programme/economie', 'LFI s''est opposée à l''inversion de la hiérarchie des normes (lois Travail/ordonnances 2017) donnant priorité aux accords d''entreprise, et défend le niveau de la branche.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q030', 2, 'sourcee'::affinite_confiance, 'https://www.institutmontaigne.org/presidentielle-2022/jean-luc-melenchon/augmenter-les-droits-de-succession-sur-les-plus-hauts-patrimoines-et-creer-un-heritage-maximal-de-12-me/', 'Plafonnement de l''héritage à 12M€, fonds au-delà redistribués notamment vers la jeunesse et la protection sociale.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q031', 2, 'deduite'::affinite_confiance, 'https://reseauactionclimat.org/presidentielle-que-vaut-jean-luc-melenchon-pour-le-climat/', 'La planification écologique est présentée comme prioritaire dans le programme, au-delà des seules considérations de compétitivité immédiate.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q032', -2, 'sourcee'::affinite_confiance, 'https://www.21news.be/melenchon-si-je-suis-elu-president-on-sortira-du-nucleaire/', 'Mélenchon défend une sortie méthodique du nucléaire (objectif autour de 2045), à l''opposé d''une relance de la construction de réacteurs.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q033', 1, 'deduite'::affinite_confiance, NULL, 'Cohérent avec sa priorité affichée à la planification écologique, même si le programme manque de précision sur l''échéance exacte (d''où confiance modérée).'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q034', 2, 'sourcee'::affinite_confiance, 'https://reseauactionclimat.org/presidentielle-que-vaut-jean-luc-melenchon-pour-le-climat/', 'Programme prévoit un "bouclier douanier écologique" avec taxe kilométrique visant les importations polluantes.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q035', 1, 'deduite'::affinite_confiance, 'https://reseauactionclimat.org/presidentielle-que-vaut-jean-luc-melenchon-pour-le-climat/', 'Réseau Action Climat relève que Mélenchon souhaite mettre fin aux ZFE "dans leur conception actuelle" sans alternative claire proposée pour la sortie du diesel/essence en ville.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q036', 2, 'deduite'::affinite_confiance, 'https://reseauactionclimat.org/presidentielle-que-vaut-jean-luc-melenchon-pour-le-climat/', 'Programme prévoit l''interdiction des pesticides et la lutte contre l''artificialisation des sols, impliquant un encadrement plus strict de l''agriculture intensive.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q037', 1, 'deduite'::affinite_confiance, 'https://reseauactionclimat.org/presidentielle-que-vaut-jean-luc-melenchon-pour-le-climat/', 'Réseau Action Climat relève un moratoire proposé sur toute nouvelle infrastructure routière, cohérent avec l''abandon de principe des grands projets contestés.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q038', -2, 'deduite'::affinite_confiance, 'https://reseauactionclimat.org/presidentielle-que-vaut-jean-luc-melenchon-pour-le-climat/', 'LFI défend un mix électrique tourné vers le renouvelable, incompatible avec un frein au développement de l''éolien terrestre.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q039', 2, 'deduite'::affinite_confiance, 'https://www.investissement-locatif.com/le-volet-logement-de-lfi-jean-luc-melenchon.html', 'Programme logement prévoit la rénovation thermique obligatoire avant toute location, cohérent avec un fléchage budgétaire prioritaire vers ce secteur.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q040', 0, 'deduite'::affinite_confiance, NULL, 'Aucune information trouvée, même par déduction idéologique — position neutre provisoire (0), à réviser dès que des éléments seront disponibles.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q041', -2, 'deduite'::affinite_confiance, 'https://www.parlons-politique.fr/international/faut-il-sortir-la-france-de-lotan-pour-gagner-en-autonomie-diplomatique-melenchon-pose-une-rupture-qui-divise-jusqua-lukraine_22261/', 'La stratégie de désobéissance aux traités européens (Plan A/B) et la défense de la souveraineté nationale vont à l''encontre d''un transfert accru de décisions vers l''UE.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q042', 1, 'deduite'::affinite_confiance, 'https://www.parlons-politique.fr/international/faut-il-sortir-la-france-de-lotan-pour-gagner-en-autonomie-diplomatique-melenchon-pose-une-rupture-qui-divise-jusqua-lukraine_22261/', 'Cohérent avec la ligne souverainiste de LFI défendant la primauté du Parlement français face aux transferts de compétences européens.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q043', 2, 'sourcee'::affinite_confiance, 'https://lafranceinsoumise.fr/2026/01/09/accord-ue-mercosur-valide-les-agriculteurs-abandonnes-par-macron-et-la-commission-europeenne/', 'LFI dénonce la mise en concurrence déloyale des agriculteurs français et plaide pour une autre politique agricole européenne protectrice.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q044', 0, 'deduite'::affinite_confiance, 'https://www.usinenouvelle.com/article/pourquoi-jean-luc-melenchon-remet-en-cause-la-dissuasion-nucleaire-pilier-de-la-defense-francaise.N1783117', 'Position ambivalente: modernisation de la dissuasion et de certains moyens soutenue, mais ligne non-alignée critique de la logique d''escalade budgétaire portée par l''OTAN.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q045', 1, 'sourcee'::affinite_confiance, 'https://www.usinenouvelle.com/article/pourquoi-jean-luc-melenchon-remet-en-cause-la-dissuasion-nucleaire-pilier-de-la-defense-francaise.N1783117', 'Mélenchon a déclaré vouloir conserver l''arsenal nucléaire comme garantie de sécurité en l''absence de désarmement multilatéral, tout en proposant un débat sur son format.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q046', -1, 'deduite'::affinite_confiance, NULL, 'Cohérent avec sa stratégie de désobéissance aux traités européens et sa méfiance générale envers l''approfondissement/élargissement de l''intégration de l''UE.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q047', 1, 'deduite'::affinite_confiance, 'https://www.afrique-asie.fr/melenchon-veut-sortir-la-france-de-lotan-et-prone-une-politique-de-non-alignement/', 'La ligne de non-alignement et de sortie de l''OTAN intégrée est cohérente avec une réduction des engagements militaires extérieurs de la France.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q048', -1, 'deduite'::affinite_confiance, 'https://www.parlons-politique.fr/international/faut-il-sortir-la-france-de-lotan-pour-gagner-en-autonomie-diplomatique-melenchon-pose-une-rupture-qui-divise-jusqua-lukraine_22261/', 'La ligne souverainiste et la stratégie de désobéissance aux traités européens rendent peu probable un soutien à un nouvel impôt européen transférant de la souveraineté fiscale.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q049', 1, 'deduite'::affinite_confiance, NULL, 'Cohérent avec sa doctrine de non-alignement international et sa volonté de diversifier les partenariats hors du cadre occidental classique.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q050', 2, 'sourcee'::affinite_confiance, 'https://lafranceinsoumise.fr/2026/01/09/accord-ue-mercosur-valide-les-agriculteurs-abandonnes-par-macron-et-la-commission-europeenne/', 'LFI a obtenu une résolution unanime de l''Assemblée contre l''accord Mercosur et déposé une motion de censure après son adoption.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q051', -1, 'deduite'::affinite_confiance, 'https://theconversation.com/securite-justice-examen-critique-des-propositions-de-benoit-hamon-et-jean-luc-melenchon-75670', 'Le programme substitue à la logique répressive une politique de prévention et de réhabilitation, plaçant la prévention avant le seul renforcement des effectifs policiers.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q052', -2, 'deduite'::affinite_confiance, 'https://theconversation.com/securite-justice-examen-critique-des-propositions-de-benoit-hamon-et-jean-luc-melenchon-75670', 'LFI s''oppose structurellement aux peines planchers, défendant une politique pénale centrée sur la réinsertion.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q053', 1, 'deduite'::affinite_confiance, 'https://theconversation.com/securite-justice-examen-critique-des-propositions-de-benoit-hamon-et-jean-luc-melenchon-75670', 'Cohérent avec la demande de LFI d''un contrôle renforcé des forces de l''ordre par une autorité indépendante, sans texte spécifique trouvé sur la caméra-piéton obligatoire.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q054', -2, 'deduite'::affinite_confiance, 'https://theconversation.com/securite-justice-examen-critique-des-propositions-de-benoit-hamon-et-jean-luc-melenchon-75670', 'Position constante de défense de la justice des mineurs (ordonnance de 1945) contre les logiques d''alignement sur le régime des majeurs.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q055', -2, 'deduite'::affinite_confiance, 'https://theconversation.com/securite-justice-examen-critique-des-propositions-de-benoit-hamon-et-jean-luc-melenchon-75670', 'Mélenchon critique la multiplication de la vidéosurveillance comme substitut à une présence humaine de proximité, défavorable à sa généralisation algorithmique.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q056', 1, 'deduite'::affinite_confiance, 'https://theconversation.com/securite-justice-examen-critique-des-propositions-de-benoit-hamon-et-jean-luc-melenchon-75670', 'La ligne du programme privilégie la prévention et la réhabilitation judiciaire, cohérente avec un renforcement prioritaire des moyens de la justice.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q057', 1, 'deduite'::affinite_confiance, 'https://theconversation.com/securite-justice-examen-critique-des-propositions-de-benoit-hamon-et-jean-luc-melenchon-75670', 'Programme axé sur la réhabilitation et le soutien aux condamnés plutôt que l''incarcération systématique.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q058', 2, 'sourcee'::affinite_confiance, 'https://www.institutmontaigne.org/presidentielle-2022/jean-luc-melenchon/legaliser-et-encadrer-par-un-monopole-detat-la-vente-production-et-consommation-de-cannabis-a-des-fins-recreatives/', 'Programme propose explicitement de légaliser et encadrer par un monopole d''État la vente, production et consommation de cannabis récréatif.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q059', -2, 'deduite'::affinite_confiance, 'https://theconversation.com/securite-justice-examen-critique-des-propositions-de-benoit-hamon-et-jean-luc-melenchon-75670', 'Ligne générale de défense des libertés individuelles face aux extensions de surveillance, défavorable à un arbitrage sacrifiant les libertés.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q060', -2, 'deduite'::affinite_confiance, 'https://theconversation.com/securite-justice-examen-critique-des-propositions-de-benoit-hamon-et-jean-luc-melenchon-75670', 'LFI privilégie les alternatives à l''incarcération et la prévention plutôt que l''extension du parc carcéral comme priorité budgétaire.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q061', -2, 'sourcee'::affinite_confiance, 'https://ccfd-terresolidaire.org/respect-des-droits-des-migrants-jean-luc-melenchon/', 'Le programme migratoire de LFI refuse toute limitation chiffrée de l''immigration légale.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q062', -2, 'deduite'::affinite_confiance, 'https://ccfd-terresolidaire.org/respect-des-droits-des-migrants-jean-luc-melenchon/', 'Position universaliste de LFI sur l''accès aux droits sociaux, cohérente avec son opposition à la suppression de l''AME et aux conditions de durée de résidence.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q063', -2, 'sourcee'::affinite_confiance, 'https://ccfd-terresolidaire.org/respect-des-droits-des-migrants-jean-luc-melenchon/', 'LFI propose au contraire de rétablir la carte de résident de 10 ans et de faciliter le regroupement familial.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q064', 2, 'sourcee'::affinite_confiance, 'https://ccfd-terresolidaire.org/respect-des-droits-des-migrants-jean-luc-melenchon/', 'Programme propose explicitement de faciliter les procédures de régularisation des travailleurs sans papiers occupant des métiers en tension.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q065', 2, 'sourcee'::affinite_confiance, 'https://www.lejdd.fr/politique/immigration-jean-luc-melenchon-compte-inscrire-le-droit-du-sol-dans-la-constitution-154904', 'LFI va au-delà du simple maintien en proposant d''inscrire le droit du sol dans la Constitution.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q066', -2, 'deduite'::affinite_confiance, 'https://ccfd-terresolidaire.org/respect-des-droits-des-migrants-jean-luc-melenchon/', 'Le groupe LFI a voté pour le rétablissement de l''AME lors de l''examen de la loi immigration 2024, s''opposant à sa suppression.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q067', 1, 'deduite'::affinite_confiance, 'https://ccfd-terresolidaire.org/respect-des-droits-des-migrants-jean-luc-melenchon/', 'Cohérent avec la politique migratoire humaniste défendue, sans chiffrage précis trouvé sur l''augmentation des capacités d''accueil.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q068', -2, 'deduite'::affinite_confiance, 'https://ccfd-terresolidaire.org/respect-des-droits-des-migrants-jean-luc-melenchon/', 'Mélenchon dénonce la création de deux catégories de Français via la déchéance de nationalité, s''opposant à ce type de mesure.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q069', -1, 'deduite'::affinite_confiance, 'https://ccfd-terresolidaire.org/respect-des-droits-des-migrants-jean-luc-melenchon/', 'LFI promeut l''apprentissage du français comme droit et outil d''intégration plutôt que comme condition contraignante assortie de "valeurs républicaines".'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q070', -2, 'deduite'::affinite_confiance, 'https://ccfd-terresolidaire.org/respect-des-droits-des-migrants-jean-luc-melenchon/', 'LFI propose de renégocier les accords de Schengen plutôt que d''en sortir, rejetant la "forteresse Europe" sans rejeter la coopération migratoire européenne.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q071', 2, 'deduite'::affinite_confiance, 'https://www.cafepedagogique.net/2017/03/23/melenchon-publie-son-programme-education/', 'Programme éducation prévoit de réduire les effectifs à 20 élèves maximum en primaire et collège, ligne reconduite dans les éditions successives.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q072', -2, 'deduite'::affinite_confiance, 'https://soseducation.org/docs/notes-etudes-entretiens-tribunes/programmes-educatifs-presidentielle-2022/programme-melenchon-ecole.pdf', 'Le programme prévoit explicitement la suspension de l''expérimentation de l''uniforme à l''école.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q073', -1, 'deduite'::affinite_confiance, 'https://soseducation.org/docs/notes-etudes-entretiens-tribunes/programmes-educatifs-presidentielle-2022/programme-melenchon-ecole.pdf', 'LFI défend une école nationale et un cadrage national du recrutement des enseignants, à l''opposé d''une autonomisation des établissements.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q074', 1, 'deduite'::affinite_confiance, 'https://soseducation.org/docs/notes-etudes-entretiens-tribunes/programmes-educatifs-presidentielle-2022/programme-melenchon-ecole.pdf', 'Programme propose de réinstaurer le redoublement comme droit à la remédiation pédagogique.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q075', 2, 'deduite'::affinite_confiance, 'https://soseducation.org/docs/notes-etudes-entretiens-tribunes/programmes-educatifs-presidentielle-2022/programme-melenchon-ecole.pdf', 'Programme prévoit d''abolir les privilèges de l''enseignement privé sous contrat, d''abroger la loi Carle et de réserver les fonds publics à l''école publique.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q076', 0, 'deduite'::affinite_confiance, 'https://www.lorientlejour.com/article/1044103/france-melenchon-precise-son-service-national-obligatoire.html', 'Mélenchon rejette le SNU actuel (jugé coûteux et problématique) mais propose son propre service citoyen obligatoire de 9-12 mois pour les 18-25 ans: accord de principe, désaccord sur le dispositif nommé SNU.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q077', -1, 'deduite'::affinite_confiance, NULL, 'Cohérent avec sa défense historique du « collège unique » et son opposition aux logiques de tri précoce des élèves.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q078', 2, 'deduite'::affinite_confiance, 'https://soseducation.org/docs/notes-etudes-entretiens-tribunes/programmes-educatifs-presidentielle-2022/programme-melenchon-ecole.pdf', 'LFI défend de longue date la gratuité de l''enseignement, y compris supérieur.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q079', 0, 'deduite'::affinite_confiance, NULL, 'Aucune information trouvée, même par déduction idéologique — position neutre provisoire (0), à réviser dès que des éléments seront disponibles.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q080', 1, 'sourcee'::affinite_confiance, 'https://www.institutmontaigne.org/presidentielle-2022/jean-luc-melenchon/creer-une-garantie-dautonomie-de-trois-ans-sous-reserve-dune-formation-qualifiante-et-sous-conditions-de-ressources-pour-les-18-25-ans/', 'Programme propose une garantie d''autonomie de 1063€/mois pour les 18-25 ans en formation, sous conditions de ressources: accord partiel, car conditionnée et non universelle.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q081', 2, 'sourcee'::affinite_confiance, 'https://www.lequotidiendumedecin.fr/actus-medicales/politique-de-sante/vous-vous-allez-dans-le-lot-dix-ans-dans-un-desert-pour-les-jeunes-medecins-la-proposition-radicale', 'Mélenchon propose d''imposer aux jeunes médecins financés par l''État de s''installer 10 ans dans les zones sous-dotées.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q082', 2, 'deduite'::affinite_confiance, 'https://melenchon.fr/2018/09/27/encore-un-plan-pour-demolir-lhopital-public/', 'Ligne constante de défense du service public hospitalier contre la place croissante du privé.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q083', 2, 'sourcee'::affinite_confiance, 'https://www.lejdd.fr/politique/aide-a-mourir-melenchon-felicite-de-tout-coeur-les-deputes-qui-ont-fait-adopter-le-texte-158529', 'Le groupe LFI a voté très majoritairement (62 pour, 1 contre) la loi sur l''aide à mourir en mai 2025; Mélenchon a félicité les députés concernés.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q084', 1, 'deduite'::affinite_confiance, 'https://www.infirmiers.com/profession-ide/jean-luc-melenchon-souhaite-une-sante-accessible-publique-et-gratuite', 'Programme vise le 100% Sécu financé notamment par l''intégration des cotisations mutuelles, logique compatible mais pas identique à une simple hausse générale des cotisations.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q085', 1, 'deduite'::affinite_confiance, 'https://www.infirmiers.com/profession-ide/jean-luc-melenchon-souhaite-une-sante-accessible-publique-et-gratuite', 'Cohérent avec l''approche globale de santé publique défendue, sans chiffrage spécifique trouvé sur la prévention/sport-santé.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q086', 2, 'deduite'::affinite_confiance, 'https://www.infirmiers.com/profession-ide/jean-luc-melenchon-souhaite-une-sante-accessible-publique-et-gratuite', 'LFI propose d''interdire les dépassements d''honoraires dans le cadre du financement du 100% Sécu.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q087', 1, 'deduite'::affinite_confiance, 'https://www.infirmiers.com/profession-ide/jean-luc-melenchon-souhaite-une-sante-accessible-publique-et-gratuite', 'Cohérent avec le renforcement général de la prise en charge par la Sécurité sociale, sans mesure chiffrée spécifique trouvée sur la santé mentale des jeunes.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q088', 1, 'deduite'::affinite_confiance, 'https://www.lequotidiendumedecin.fr/actus-medicales/politique-de-sante/vous-vous-allez-dans-le-lot-dix-ans-dans-un-desert-pour-les-jeunes-medecins-la-proposition-radicale', 'Programme vise la fin du numerus clausus associée à un renforcement des moyens des facultés de médecine, davantage une réforme structurelle qu''une simple suppression sèche.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q089', 2, 'deduite'::affinite_confiance, 'https://www.infirmiers.com/profession-ide/jean-luc-melenchon-souhaite-une-sante-accessible-publique-et-gratuite', 'Programme prévoit l''intégration des mutuelles à la Sécurité sociale dans le cadre du 100% Sécu, réduisant leur rôle autonome.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q090', -2, 'sourcee'::affinite_confiance, 'https://twitter.com/jlmelenchon/status/1416013335150145543', 'Mélenchon et le groupe LFI se sont déclarés opposés à la vaccination obligatoire, y compris de façon déguisée via le passe sanitaire/vaccinal.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q091', 2, 'deduite'::affinite_confiance, 'https://www.investissement-locatif.com/le-volet-logement-de-lfi-jean-luc-melenchon.html', 'Programme prévoit de relever le quota SRU à 30% et de renforcer les sanctions contre les communes récalcitrantes.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q092', 2, 'sourcee'::affinite_confiance, 'https://www.institutmontaigne.org/presidentielle-2022/jean-luc-melenchon/encadrer-les-loyers-partout-sur-le-territoire-et-a-la-baisse-dans-les-grandes-villes/', 'Programme 2022 prévoit d''encadrer les loyers partout sur le territoire et à la baisse dans les grandes villes.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q093', 1, 'deduite'::affinite_confiance, 'https://melenchon2027.fr/livrets-2022/ruralite/', 'Programme ruralité défend l''égalité républicaine et le maintien des services publics de proximité en zone rurale.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q094', 0, 'deduite'::affinite_confiance, 'https://www.investissement-locatif.com/le-volet-logement-de-lfi-jean-luc-melenchon.html', 'Position en tension: construction de 200 000 logements sociaux/an visée, tout en luttant contre l''artificialisation des sols via réhabilitation plutôt qu''extension.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q095', 2, 'deduite'::affinite_confiance, 'https://news.lesiteimmo.com/2025/12/16/taxe-residences-secondaires-logements-vacants-reforme/', 'Programme prévoit une fiscalité fortement alourdie sur les logements vacants/sous-utilisés en zones tendues.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q096', 0, 'deduite'::affinite_confiance, 'https://www.politis.fr/articles/2026/07/politique-ecologie-une-france-des-ecoregions-le-reve-insoumis-dune-decentralisation-verte/', 'Position ambivalente: LFI veut renforcer communes et créer des écorégions tout en supprimant les "méga-régions" et métropoles technocratiques actuelles, ce qui n''est pas un simple renforcement du pouvoir des régions existantes.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q097', 1, 'deduite'::affinite_confiance, 'https://www.politis.fr/articles/2026/07/politique-ecologie-une-france-des-ecoregions-le-reve-insoumis-dune-decentralisation-verte/', 'Programme critique les métropoles technocratiques et souhaite rééquilibrer les moyens vers les communes et la ruralité.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q098', 1, 'deduite'::affinite_confiance, 'https://www.politis.fr/articles/2026/07/politique-ecologie-une-france-des-ecoregions-le-reve-insoumis-dune-decentralisation-verte/', 'Programme propose de mettre les infrastructures numériques sous contrôle public, cohérent avec un investissement prioritaire en zone rurale.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q099', 2, 'deduite'::affinite_confiance, 'https://www.politis.fr/articles/2026/07/politique-ecologie-une-france-des-ecoregions-le-reve-insoumis-dune-decentralisation-verte/', 'Programme prévoit de limiter les meublés touristiques à 60 jours/an, des quotas en zones tendues et leur interdiction en hyper-centre des grandes métropoles.'),
  ('e847e671-08c5-4562-859e-dde70d07371b'::uuid, 'Q100', 2, 'deduite'::affinite_confiance, 'https://www.investissement-locatif.com/le-volet-logement-de-lfi-jean-luc-melenchon.html', 'Le droit au logement effectif est un thème central et constant du programme logement de LFI (construction massive de logements sociaux, réquisition des logements vacants, objectif zéro sans-abri).')
) as v(candidate_id, question_id, position, confiance, source_url, note)
where t.candidate_id = v.candidate_id
  and t.question_id = v.question_id;

