  ('75859e45-95bb-42bb-8e93-ab0b52fd8b30'::uuid, 'Q002', -2, 'sourcee'::affinite_confiance, 'https://www.europe1.fr/politique/le-referendum-dinitiative-citoyenne-ca-me-herisse-declare-edouard-philippe-3845711', 'Déclaration directe et répétée : "le RIC, ça me hérisse", préfère le référendum d''initiative partagée existant.'),
  ('75859e45-95bb-42bb-8e93-ab0b52fd8b30'::uuid, 'Q003', 1, 'deduite'::affinite_confiance, 'https://www.france24.com/fr/20180404-france-reforme-institutions-edouard-philippe-moins-parlementaires-15-proportionnelle', 'Son projet de réforme institutionnelle de 2018 (PM) prévoyait une limitation du cumul des mandats dans le temps.'),
  ('75859e45-95bb-42bb-8e93-ab0b52fd8b30'::uuid, 'Q004', -1, 'sourcee'::affinite_confiance, 'https://www.publicsenat.fr/actualites/non-classe/edouard-philippe-l-introduction-de-10-ou-25-de-proportionnelle-ne-remet-pas-en-cause-les-institutions', 'Ne défend qu''une "dose" de 15% de proportionnelle, pas un remplacement total du scrutin majoritaire.'),
